export interface ConnectorConfig {
  /** Slack channel ID (e.g., C0123456789) or name (e.g., #general) */
  channel: string
  /** Slack Bot User OAuth Token (xoxb-...). Usually from SLACK_BOT_TOKEN env var. */
  slackBotToken: string
  /** Injected fetch for testing; defaults to global fetch in production. */
  fetch?: typeof fetch
}

export interface CalendlyInviteeCreatedPayload {
  invitee: {
    name: string
    email: string
  }
  answers?: Record<string, string>
}

export interface SlackPostMessageResponse {
  ok: boolean
  channel: string
  ts: string
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
}

function formatMessage(payload: CalendlyInviteeCreatedPayload): string {
  const lines = ['New meeting booked!']
  lines.push(`Name: ${payload.invitee.name}`)
  lines.push(`Email: ${payload.invitee.email}`)
  if (payload.answers && Object.keys(payload.answers).length > 0) {
    const answersStr = Object.entries(payload.answers)
      .map(([q, a]) => `${q}: ${a}`)
      .join(', ')
    lines.push(`Answers: ${answersStr}`)
  }
  return lines.join('\n')
}

export async function handle(
  payload: CalendlyInviteeCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.invitee?.name) {
    throw new Error('Missing required field: invitee.name')
  }
  if (!payload.invitee?.email) {
    throw new Error('Missing required field: invitee.email')
  }
  if (!config.channel) {
    throw new Error('Missing required config: channel')
  }
  if (!config.slackBotToken) {
    throw new Error('Missing required config: slackBotToken')
  }

  const text = formatMessage(payload)

  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.slackBotToken}`,
    },
    body: JSON.stringify({ channel: config.channel, text }),
  })

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} for POST https://slack.com/api/chat.postMessage`,
    )
  }

  const data = (await response.json()) as SlackPostMessageResponse
  return { slackMessageTs: data.ts, slackChannel: data.channel }
}

